  { id: "sahabdulaziz", ad: "Şah Abdülazîz ed-Dihlevî", ar: "شاه عبد العزيز الدهلوي", olum: "1239/1824", y: 13, sehir: "Delhi", ekol: "Hanefî; hadis ve tasavvuf",
    hocalar: ["dihlevi"], talebeler: [],
    ozet: "Şah Veliyyullah ed-Dihlevî'nin oğlu ve ilminin varisidir. Babasının Delhi'deki medresesini sürdürdü ve Hindistan'daki hadis geleneğini bir sonraki nesle aktardı. İngiliz hâkimiyeti altındaki Hindistan'ın “dârülharp” olduğuna dair fetvası, Hint Müslümanlarının sömürgeye karşı tutumunu derinden etkiledi.",
    metod: "Babasının ıslah yolunu sürdürdü. Hadis öğretimini ve Kur'an'ın Farsça açıklamasını öncelikli tuttu.",
    alan: ["Hadis", "Tefsir", "Kelâm"], etki: "Tuhfe-i İsnâaşeriyye, Sünnî-Şiî tartışmasının en kapsamlı Farsça eserlerinden biridir. Bu eserin Arapça özeti Osmanlı'da da okundu. Bustânü'l-muhaddisîn, hadis kitaplarının tarihine dair kısa ve değerli bir eserdir.",
    okuma: "Bustânü'l-muhaddisîn, hadis kitaplarının nasıl oluştuğuna dair kısa bir giriş olarak okunabilir.",
    gorus: ["Sömürge yönetiminin İslâm hukuku açısından değerlendirilmesinde dârülharp kavramını kullandı.", "Şiî itirazlarına karşı Ehl-i sünnet görüşlerini delilleriyle savundu.", "Kur'an'ı halkın anlayacağı dilde tefsir etmeyi ve hadisi yaygınlaştırmayı amaçladı."],
    eser: [["Tuhfe-i İsnâaşeriyye", "Sünnî-Şiî tartışması."], ["Fethu'l-azîz", "Farsça tefsir (bir kısmı)."], ["Bustânü'l-muhaddisîn", "Hadis kitaplarının tarihi."]], soz: [], hakkinda: [] },
  { id: "bacuri", ad: "İbrâhim el-Bâcûrî", ar: "إبراهيم الباجوري", olum: "1276/1860", y: 13, sehir: "Bâcûr (Mısır), Kahire", ekol: "Şâfiî; Eş'arî",
    hocalar: ["Muhammed el-Fudâlî"], talebeler: [],
    ozet: "Ezher şeyhidir. Lekānî'nin Cevheretü't-tevhîd manzumesine yazdığı Tuhfetü'l-mürîd, son dönem Eş'arî akaidinin en çok okunan şerhlerindendir. İbn Kāsım'ın Şâfiî fıkıh şerhine yazdığı haşiye de Şâfiî medreselerinde yaygın olarak okutulur.",
    metod: "Önceki şerhleri özetleyip haşiye geleneğinin öğretici imkânlarını kullandı.",
    alan: ["Kelâm", "Fıkıh"], etki: "Haşiyeleri 19. ve 20. yüzyılda Ezher'den Endonezya'ya kadar uzanan medrese müfredatlarında temel ders kitabı oldu.",
    okuma: "Tuhfetü'l-mürîd, Eş'arî akaidini klasik şerh geleneği içinde öğrenmek isteyenler için önerilir.",
    gorus: ["Eş'arî akaidini müteahhir dönemdeki kesinleşmiş şekliyle öğretti.", "Taklitçinin imanının sahih olup olmadığı tartışmasında, ehl-i sünnetin görüşlerini karşılaştırarak aktardı.", "Fıkıh ve akaid öğretimini haşiye geleneği içinde sürdürdü."],
    eser: [["Tuhfetü'l-mürîd alâ Cevhereti't-tevhîd", "Eş'arî akaid şerhi."], ["Hâşiye alâ İbn Kāsım", "Şâfiî fıkhı haşiyesi."]], soz: [], hakkinda: [] }
